def ocr_engine() -> Any:
    global _ocr
    if _ocr is None:
        prepare_paddle_runtime()
        from paddleocr import PaddleOCR

        _ocr = PaddleOCR(
            lang="en",
            text_detection_model_name="PP-OCRv6_small_det",
            text_recognition_model_name="PP-OCRv6_small_rec",
            use_doc_orientation_classify=False,
            use_doc_unwarping=False,
            use_textline_orientation=True,
        )
    return _ocr


def safe_name(filename: str) -> str:
    stem = Path(filename).stem.replace(" ", "_")[:80] or "upload"
    suffix = Path(filename).suffix.lower() or ".bin"
    return f"{int(time.time())}_{uuid.uuid4().hex[:8]}_{stem}{suffix}"


def polygon_overlap_ratio(poly_a: list[list[float]], poly_b: list[list[float]]) -> float:
    pts_a = np.array(poly_a, dtype=np.float32)
    pts_b = np.array(poly_b, dtype=np.float32)
    area_a = float(cv2.contourArea(pts_a))
    area_b = float(cv2.contourArea(pts_b))
    if area_a <= 0 or area_b <= 0:
        return 0.0
    intersection_area, _ = cv2.intersectConvexConvex(pts_a, pts_b)
    return float(intersection_area) / min(area_a, area_b)


def polygon_area(poly: list[list[float]]) -> float:
    return abs(float(cv2.contourArea(np.array(poly, dtype=np.float32))))


def polygon_bbox(poly: list[list[float]]) -> tuple[float, float, float, float]:
    pts = np.array(poly, dtype=np.float32)
    xs = pts[:, 0]
    ys = pts[:, 1]
    return float(xs.min()), float(ys.min()), float(xs.max()), float(ys.max())


def bbox_gap(a: tuple[float, float, float, float], b: tuple[float, float, float, float]) -> float:
    ax1, ay1, ax2, ay2 = a
    bx1, by1, bx2, by2 = b
    dx = max(bx1 - ax2, ax1 - bx2, 0)
    dy = max(by1 - ay2, ay1 - by2, 0)
    return float((dx * dx + dy * dy) ** 0.5)


def bbox_overlap_ratio(a: tuple[float, float, float, float], b: tuple[float, float, float, float]) -> float:
    ax1, ay1, ax2, ay2 = a
    bx1, by1, bx2, by2 = b
    ix1, iy1 = max(ax1, bx1), max(ay1, by1)
    ix2, iy2 = min(ax2, bx2), min(ay2, by2)
    iw, ih = max(ix2 - ix1, 0), max(iy2 - iy1, 0)
    inter = iw * ih
    area_a = max((ax2 - ax1) * (ay2 - ay1), 1)
    area_b = max((bx2 - bx1) * (by2 - by1), 1)
    return float(inter / min(area_a, area_b))


def normalize_ocr_text(text: str) -> str:
    text = text.lower()
    replacements = {
        "ä": "a",
        "ö": "o",
        "ü": "u",
        "ß": "ss",
        "é": "e",
        "è": "e",
        "ê": "e",
        "á": "a",
        "à": "a",
        "í": "i",
        "ó": "o",
        "ç": "c",
        "ğ": "g",
    }
    for src, dst in replacements.items():
        text = text.replace(src, dst)
    text = re.sub(r"[^a-z0-9@./+ -]+", " ", text)
    return re.sub(r"\s+", " ", text).strip()


OCR_ACCESSORY_MATCH_MIN_TEXT_SCORE = 0.65
OCR_ACCESSORY_MATCH_MIN_CONFIDENCE = 0.60
OCR_ACCESSORY_MATCH_MIN_MARGIN = 0.15
OCR_ACCESSORY_PROFILE_STOPWORDS = {
    "accessory",
    "document",
    "documentation",
    "instruction",
    "instructions",
    "label",
    "manual",
    "paper",
    "product",
    "text",
    "and",
    "back",
    "cover",
    "for",
    "from",
    "image",
    "images",
    "shows",
    "the",
    "that",
    "this",
    "white",
    "with",
}


def ocr_keyword_terms(value: Any, *, weight: float = 1.0) -> list[dict[str, Any]]:
    terms: list[dict[str, Any]] = []
    if value is None:
        return terms
    if isinstance(value, dict):
        for nested in value.values():
            terms.extend(ocr_keyword_terms(nested, weight=weight))
        return terms
    if isinstance(value, list):
        for nested in value:
            terms.extend(ocr_keyword_terms(nested, weight=weight))
        return terms
    normalized = normalize_ocr_text(str(value))
    if not normalized:
        return terms
    if len(normalized) >= 3 and normalized not in OCR_ACCESSORY_PROFILE_STOPWORDS:
        terms.append({"text": normalized, "weight": weight})
    for token in normalized.split():
        if len(token) >= 3 and token not in OCR_ACCESSORY_PROFILE_STOPWORDS:
            terms.append({"text": token, "weight": weight})
    return terms


def build_ocr_accessory_profiles(items: list[dict[str, Any]], accessory_labels: dict[str, str]) -> dict[str, dict[str, Any]]:
    profiles: dict[str, dict[str, Any]] = {}
    for item in items:
        if not item:
            continue
        accessory_id = str(item.get("id") or accessory_uid(item) or "").strip()
        if not accessory_id:
            continue
        profile = item.get("ai_profile") if isinstance(item.get("ai_profile"), dict) else {}
        label = str(accessory_labels.get(accessory_id) or item.get("name") or item.get("label") or accessory_id)
        raw_terms: list[dict[str, Any]] = []
        raw_terms.extend(ocr_keyword_terms(label, weight=2.0))
        raw_terms.extend(ocr_keyword_terms(item.get("name"), weight=2.0))
        raw_terms.extend(ocr_keyword_terms(item.get("label"), weight=2.0))
        raw_terms.extend(ocr_keyword_terms(profile.get("english_name"), weight=2.0))
        raw_terms.extend(ocr_keyword_terms(profile.get("distinguishing_text"), weight=3.0))
        raw_terms.extend(ocr_keyword_terms(profile.get("tags"), weight=1.0))
        keywords: dict[str, float] = {}
        for term in raw_terms:
            text = str(term.get("text") or "").strip()
            if not text:
                continue
            keywords[text] = max(float(term.get("weight") or 1.0), keywords.get(text, 0.0))
        profiles[accessory_id] = {
            "accessory_id": accessory_id,
            "label": label,
            "keywords": [{"text": text, "weight": weight} for text, weight in sorted(keywords.items())],
        }
    return profiles


def match_ocr_text_accessory(texts: list[str], mean_text_score: float, spec: dict[str, Any]) -> dict[str, Any]:
    joined = normalize_ocr_text(" ".join(texts))
    profiles = spec.get("ocr_accessory_profiles") if isinstance(spec.get("ocr_accessory_profiles"), dict) else {}
    if not joined or not profiles:
        return {"accepted": False, "reason": "no_ocr_text_or_profiles", "confidence": 0.0, "margin": 0.0}
    scores: list[dict[str, Any]] = []
    for accessory_id, profile in profiles.items():
        hits = []
        score = 0.0
        for keyword in profile.get("keywords") or []:
            text = str(keyword.get("text") or "").strip()
            if text and text in joined:
                weight = float(keyword.get("weight") or 1.0)
                score += weight
                hits.append(text)
        confidence = min(1.0, score / 6.0) if score > 0 else 0.0
        scores.append(
            {
                "accessory_id": str(accessory_id),
                "label": str(profile.get("label") or accessory_id),
                "score": round(score, 4),
                "confidence": round(confidence, 4),
                "matched_keywords": hits[:12],
            }
        )
    ranked = sorted(scores, key=lambda item: (float(item["confidence"]), float(item["score"])), reverse=True)
    best = ranked[0] if ranked else {"confidence": 0.0, "score": 0.0}
    second_confidence = float(ranked[1]["confidence"]) if len(ranked) > 1 else 0.0
    margin = round(float(best.get("confidence") or 0.0) - second_confidence, 4)
    accepted = (
        float(mean_text_score) >= OCR_ACCESSORY_MATCH_MIN_TEXT_SCORE
        and float(best.get("confidence") or 0.0) >= OCR_ACCESSORY_MATCH_MIN_CONFIDENCE
        and margin >= OCR_ACCESSORY_MATCH_MIN_MARGIN
    )
    reason = "accepted" if accepted else "low_ocr_confidence"
    if float(mean_text_score) < OCR_ACCESSORY_MATCH_MIN_TEXT_SCORE:
        reason = "low_text_score"
    elif float(best.get("confidence") or 0.0) < OCR_ACCESSORY_MATCH_MIN_CONFIDENCE:
        reason = "low_match_confidence"
    elif margin < OCR_ACCESSORY_MATCH_MIN_MARGIN:
        reason = "low_match_margin"
    return {
        "accepted": accepted,
        "reason": reason,
        "accessory_id": best.get("accessory_id"),
        "label": best.get("label"),
        "confidence": best.get("confidence", 0.0),
        "margin": margin,
        "mean_text_score": round(float(mean_text_score), 4),
        "matched_keywords": best.get("matched_keywords", []),
        "candidates": ranked[:5],
    }


def classify_manual_text(texts: list[str]) -> dict[str, Any]:
    joined = normalize_ocr_text(" ".join(texts))
    scores: dict[str, int] = {}
    matches: dict[str, list[str]] = {}
    for manual_type, keywords in MANUAL_TYPE_KEYWORDS.items():
        score = 0
        hit_list = []
        for keyword, weight in keywords:
            key = normalize_ocr_text(keyword)
            if key and key in joined:
                score += weight
                hit_list.append(keyword)
        scores[manual_type] = score
        matches[manual_type] = hit_list

    best_type, best_score = max(scores.items(), key=lambda item: item[1])
    second_score = max((score for key, score in scores.items() if key != best_type), default=0)
    if best_score < 6 or best_score - second_score < 2:
        best_type = "unknown"
    confidence = 0.0 if best_type == "unknown" else min(1.0, best_score / max(best_score + second_score, 1))
    return {
        "manual_type": best_type,
        "manual_label": MANUAL_TYPE_LABELS.get(best_type, "Unknown Manual"),
        "confidence": round(confidence, 4),
        "scores": scores,
        "matches": matches.get(best_type, []),
    }


def rotate_quarter_turn(image_bgr: np.ndarray, angle: int) -> np.ndarray:
    normalized = int(angle) % 360
    if normalized == 0:
        return image_bgr
    if normalized == 90:
        return cv2.rotate(image_bgr, cv2.ROTATE_90_CLOCKWISE)
    if normalized == 180:
        return cv2.rotate(image_bgr, cv2.ROTATE_180)
    if normalized == 270:
        return cv2.rotate(image_bgr, cv2.ROTATE_90_COUNTERCLOCKWISE)
    raise ValueError(f"angle must be a quarter turn, got {angle}")


def resize_for_ocr(crop_bgr: np.ndarray, max_long_side: int) -> np.ndarray:
    if max_long_side <= 0:
        return crop_bgr
    height, width = crop_bgr.shape[:2]
    long_side = max(height, width)
    if long_side <= max_long_side:
        return crop_bgr
    scale = max_long_side / long_side
    return cv2.resize(
        crop_bgr,
        (max(1, int(round(width * scale))), max(1, int(round(height * scale)))),
        interpolation=cv2.INTER_AREA,
    )


def crop_detection_region(
    image_bgr: np.ndarray,
    polygon: list[list[float]],
    padding: int = 20,
    max_long_side: int = 750,
) -> tuple[np.ndarray, dict[str, Any]] | None:
    height, width = image_bgr.shape[:2]
    pts = np.array(polygon, dtype=np.float32)
    if len(pts) < 3:
        return None
    x1 = max(0, int(np.floor(pts[:, 0].min())) - padding)
    y1 = max(0, int(np.floor(pts[:, 1].min())) - padding)
    x2 = min(width, int(np.ceil(pts[:, 0].max())) + padding)
    y2 = min(height, int(np.ceil(pts[:, 1].max())) + padding)
    if x2 <= x1 or y2 <= y1:
        return None
    crop = image_bgr[y1:y2, x1:x2]
    shifted = pts.copy()
    shifted[:, 0] -= x1
    shifted[:, 1] -= y1
    mask = np.zeros(crop.shape[:2], dtype=np.uint8)
    cv2.fillPoly(mask, [np.round(shifted).astype(np.int32)], 255)
    white = np.full_like(crop, 255)
    masked = np.where(mask[:, :, None] > 0, crop, white)

    rect = cv2.minAreaRect(shifted)
    rect_width, rect_height = rect[1]
    long_edge_angle = 0.0
    if rect_width > 0 and rect_height > 0:
        box = cv2.boxPoints(rect)
        edges = []
        for idx in range(4):
            p1 = box[idx]
            p2 = box[(idx + 1) % 4]
            vector = p2 - p1
            length = float(np.linalg.norm(vector))
            angle = float(np.degrees(np.arctan2(vector[1], vector[0])))
            edges.append((length, angle))
        long_edge_angle = max(edges, key=lambda item: item[0])[1]

    # Manuals are portrait documents. Rotate to make the long edge vertical,
    # using only a single quarter-turn before the default OCR pass.
    correction = int(round((90.0 - long_edge_angle) / 90.0) * 90) % 360
    if correction == 0 and 35.0 <= abs(long_edge_angle) <= 75.0:
        correction = 180
    oriented = rotate_quarter_turn(masked, correction)
    oriented = resize_for_ocr(oriented, max_long_side)
    return oriented, {
        "long_edge_angle": round(long_edge_angle, 2),
        "predicted_rotation": correction,
        "fallback_rotations": [(correction + 180) % 360],
    }


def build_ocr_result(result: dict[str, Any], rotation: int) -> dict[str, Any]:
    texts = [str(x) for x in result.get("rec_texts", []) if str(x).strip()]
    rec_scores = [float(x) for x in result.get("rec_scores", [])]
    mean_score = sum(rec_scores) / len(rec_scores) if rec_scores else 0.0
    return {
        "texts": texts,
        "mean_text_score": round(mean_score, 4),
        "rotation": int(rotation) % 360,
        "classification": classify_manual_text(texts),
    }


def score_ocr_variant(crop_bgr: np.ndarray, rotation: int) -> dict[str, Any]:
    try:
        result = ocr_engine().predict(cv2.cvtColor(crop_bgr, cv2.COLOR_BGR2RGB))[0]
    except Exception:
        result = {}
    return build_ocr_result(result, rotation)


def score_ocr_variants(crops_bgr: list[np.ndarray], rotations: list[int]) -> list[dict[str, Any]]:
    if not crops_bgr:
        return []
    try:
        batch = [cv2.cvtColor(crop, cv2.COLOR_BGR2RGB) for crop in crops_bgr]
        results = ocr_engine().predict(batch)
        return [build_ocr_result(result or {}, rotation) for result, rotation in zip(results, rotations)]
    except Exception:
        return [score_ocr_variant(crop, rotation) for crop, rotation in zip(crops_bgr, rotations)]


def is_confident_manual_classification(ocr_result: dict[str, Any], min_confidence: float) -> bool:
    classification = ocr_result["classification"]
    return classification["manual_type"] != "unknown" and float(classification["confidence"]) >= min_confidence


def better_ocr_result(current: dict[str, Any], candidate: dict[str, Any]) -> dict[str, Any]:
    current_class_score = max(current["classification"]["scores"].values(), default=0)
    candidate_class_score = max(candidate["classification"]["scores"].values(), default=0)
    if (
        candidate_class_score,
        len(candidate["texts"]),
        candidate["mean_text_score"],
    ) > (
        current_class_score,
        len(current["texts"]),
        current["mean_text_score"],
    ):
        return candidate
    return current


def run_ocr_on_crop(
    crop_bgr: np.ndarray,
    orientation: dict[str, Any],
    fallback_min_confidence: float,
) -> dict[str, Any]:
    best = score_ocr_variant(crop_bgr, int(orientation["predicted_rotation"]))
    fallback_used = False
    if not is_confident_manual_classification(best, fallback_min_confidence):
        for fallback_rotation in orientation.get("fallback_rotations", []):
            fallback_crop = rotate_quarter_turn(crop_bgr, 180)
            candidate = score_ocr_variant(fallback_crop, int(fallback_rotation))
            fallback_used = True
            best = better_ocr_result(best, candidate)
            if is_confident_manual_classification(best, fallback_min_confidence):
                break
    best["fallback_used"] = fallback_used
    best["orientation"] = orientation
    return best


def finalize_ocr_detection(
    det: dict[str, Any],
    ocr_result: dict[str, Any],
    orientation: dict[str, Any],
    max_texts: int,
) -> None:
    classification = ocr_result["classification"]
    det["ocr"] = {
        **classification,
        "best_rotation": ocr_result["rotation"],
        "predicted_rotation": orientation["predicted_rotation"],
        "long_edge_angle": orientation["long_edge_angle"],
        "fallback_used": ocr_result.get("fallback_used", False),
        "mean_text_score": ocr_result["mean_text_score"],
        "texts": ocr_result["texts"][:max_texts],
    }
    if classification["manual_type"] != "unknown":
        manual_type = classification["manual_type"]
        class_id = MANUAL_TYPE_CLASS_IDS[manual_type]
        det["class_id"] = class_id
        det["class_name"] = CLASS_NAMES[class_id]
        det["label"] = CLASS_LABELS[class_id]
        det["manual_type"] = manual_type
        det["manual_label"] = classification["manual_label"]
    else:
        det["class_id"] = 99
        det["class_name"] = GENERIC_DETECTION_CLASS_NAMES[99]
        det["label"] = GENERIC_DETECTION_LABELS[99]


def attach_ocr_results(
    image_bgr: np.ndarray,
    detections: list[dict[str, Any]],
    config: dict[str, Any],
    spec: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    if not config.get("ocr", {}).get("enabled", True):
        return detections
    spec = spec or {}
    ocr_config = config.get("ocr", {})
    max_texts = int(ocr_config.get("max_texts_per_manual", 16))
    max_crop_long_side = int(ocr_config.get("max_crop_long_side", 750))
    fallback_min_confidence = float(ocr_config.get("fallback_min_confidence", 0.55))
    if spec.get("is_specialized"):
        ocr_model_class_ids = {int(x) for x in spec.get("ocr_model_class_ids") or []}
    else:
        ocr_model_class_ids = {1}
    jobs = []
    for det in detections:
        if int(det.get("model_class_id", det["class_id"])) not in ocr_model_class_ids:
            continue
        crop_result = crop_detection_region(
            image_bgr,
            det["polygon"],
            max_long_side=max_crop_long_side,
        )
        if crop_result is None:
            det["ocr"] = {"manual_type": "unknown", "manual_label": "Unknown Manual", "texts": []}
            continue
        crop, orientation = crop_result
        jobs.append({"det": det, "crop": crop, "orientation": orientation})

    if not jobs:
        return detections

    default_results = score_ocr_variants(
        [job["crop"] for job in jobs],
        [int(job["orientation"]["predicted_rotation"]) for job in jobs],
    )
    fallback_indexes = [
        idx
        for idx, result in enumerate(default_results)
        if not is_confident_manual_classification(result, fallback_min_confidence)
    ]
    if fallback_indexes:
        fallback_results = score_ocr_variants(
            [rotate_quarter_turn(jobs[idx]["crop"], 180) for idx in fallback_indexes],
            [int(jobs[idx]["orientation"]["fallback_rotations"][0]) for idx in fallback_indexes],
        )
        for idx, fallback_result in zip(fallback_indexes, fallback_results):
            fallback_result["fallback_used"] = True
            default_results[idx] = better_ocr_result(default_results[idx], fallback_result)

    for job, ocr_result in zip(jobs, default_results):
        ocr_result.setdefault("fallback_used", False)
        if spec.get("is_specialized"):
            classification = ocr_result["classification"]
            accessory_match = match_ocr_text_accessory(ocr_result["texts"], float(ocr_result["mean_text_score"]), spec)
            job["det"]["ocr"] = {
                **classification,
                "best_rotation": ocr_result["rotation"],
                "orientation": job["orientation"],
                "fallback_used": ocr_result.get("fallback_used", False),
                "mean_text_score": ocr_result["mean_text_score"],
                "texts": ocr_result["texts"][:max_texts],
                "accessory_match": accessory_match,
            }
            job["det"]["manual_type"] = classification["manual_type"]
            job["det"]["manual_label"] = classification["manual_label"]
            job["det"].setdefault("yolo_accessory_id", job["det"].get("accessory_id"))
            if accessory_match.get("accepted") and accessory_match.get("accessory_id"):
                resolved_id = str(accessory_match["accessory_id"])
                label = str(accessory_match.get("label") or spec.get("accessory_labels", {}).get(resolved_id) or resolved_id)
                job["det"]["resolved_accessory_id"] = resolved_id
                job["det"]["accessory_id"] = resolved_id
                job["det"]["label"] = label
                job["det"]["class_name"] = label
                job["det"]["resolution_source"] = "ocr"
            else:
                fallback_id = str(job["det"].get("yolo_accessory_id") or job["det"].get("accessory_id") or "")
                job["det"]["resolved_accessory_id"] = fallback_id
                job["det"]["resolution_source"] = f"yolo_fallback_{accessory_match.get('reason') or 'ocr_rejected'}"
        else:
            finalize_ocr_detection(job["det"], ocr_result, job["orientation"], max_texts)
    return detections


def filter_detections(detections: list[dict[str, Any]], image_shape: tuple[int, int]) -> list[dict[str, Any]]:
    height, width = image_shape
    image_area = max(height * width, 1)
    filtered = []
    for det in detections:
        area = polygon_area(det["polygon"])
        det["area_px"] = round(area, 2)
        cls_id = int(det["class_id"])
        confidence = float(det["confidence"])
        area_ratio = area / image_area
        if cls_id == 0 and (
            confidence < 0.55
            or area_ratio < 0.0015
            or (area_ratio < 0.003 and confidence < 0.85)
        ):
            continue
        if cls_id in (1, 2, 3, 4, 99) and (confidence < 0.30 or area_ratio < 0.006):
            continue
        filtered.append(det)
    return filtered


def dedupe_detections(
    detections: list[dict[str, Any]],
    overlap_threshold: float = 0.08,
    adjacent_gap_px: float = 42.0,
    absorb_area_ratio: float = 0.22,
) -> list[dict[str, Any]]:
    kept: list[dict[str, Any]] = []
    for det in sorted(detections, key=lambda item: float(item["confidence"]), reverse=True):
        cls_id = int(det["class_id"])
        det_area = polygon_area(det["polygon"])
        det_bbox = polygon_bbox(det["polygon"])
        duplicate = False
        for other in kept:
            if int(other["class_id"]) != cls_id:
                continue
            other_area = polygon_area(other["polygon"])
            other_bbox = polygon_bbox(other["polygon"])
            min_area = max(min(det_area, other_area), 1)
            max_area = max(det_area, other_area, 1)
            overlap = bbox_overlap_ratio(det_bbox, other_bbox)
            close = bbox_gap(det_bbox, other_bbox) <= adjacent_gap_px
            small_fragment = min_area / max_area <= absorb_area_ratio
            near_small_fragment = cls_id == 1 and small_fragment and (overlap >= overlap_threshold or close)
            low_conf_adjacent_manual = (
                cls_id == 1
                and close
                and max(det_area, other_area) < 250000
                and float(det["confidence"]) < 0.55
                and float(other["confidence"]) < 0.55
            )
            near_duplicate = small_fragment and overlap >= 0.65
            if near_small_fragment or low_conf_adjacent_manual or near_duplicate:
                duplicate = True
                break
        if not duplicate:
            kept.append(det)
    return kept


def postprocess_detections(detections: list[dict[str, Any]], image_shape: tuple[int, int]) -> list[dict[str, Any]]:
    return dedupe_detections(filter_detections(detections, image_shape))


def detection_names_for_business_class(business_cls_id: int, spec: dict[str, Any]) -> tuple[str, str]:
    if spec.get("is_specialized"):
        name = str(spec.get("rule_class_labels", {}).get(business_cls_id) or spec.get("model_class_names", {}).get(business_cls_id, f"class_{business_cls_id}"))
        return name, name
    if spec.get("uses_ocr") and business_cls_id == 1:
        return GENERIC_DETECTION_CLASS_NAMES[1], GENERIC_DETECTION_LABELS[1]
    return CLASS_NAMES.get(business_cls_id, f"class_{business_cls_id}"), CLASS_LABELS.get(business_cls_id, f"Class {business_cls_id}")


def parse_detections(result: Any, spec: dict[str, Any]) -> list[dict[str, Any]]:
    detections = []
    image_shape = tuple(int(x) for x in result.orig_shape[:2])
    model_to_business = spec["model_to_business_class"]
    model_class_names = spec["model_class_names"]
    model_to_accessory_id = {int(k): str(v) for k, v in (spec.get("model_to_accessory_id") or {}).items()}
    if result.boxes is not None and len(result.boxes) > 0:
        classes = result.boxes.cls.cpu().numpy().astype(int)
        confidences = result.boxes.conf.cpu().numpy()
        if result.masks is not None:
            polygons = list(result.masks.xy)
        else:
            # Detection model (boxes only, no mask): synthesise an axis-aligned
            # rectangle polygon from each xyxy box so the downstream count / OCR /
            # drawing pipeline keeps working unchanged.
            xyxy = result.boxes.xyxy.cpu().numpy()
            polygons = [
                np.array([[bx1, by1], [bx2, by1], [bx2, by2], [bx1, by2]], dtype=np.float32)
                for bx1, by1, bx2, by2 in xyxy
            ]
        for model_cls_id, conf, polygon in zip(classes, confidences, polygons):
            business_cls_id = model_to_business.get(int(model_cls_id))
            if business_cls_id is None or len(polygon) < 3:
                continue
            accessory_id = model_to_accessory_id.get(int(model_cls_id))
            class_name, label = detection_names_for_business_class(business_cls_id, spec)
            detections.append(
                {
                    "class_id": business_cls_id,
                    "accessory_id": accessory_id,
                    "yolo_accessory_id": accessory_id,
                    "resolved_accessory_id": accessory_id,
                    "resolution_source": "yolo",
                    "class_name": class_name,
                    "label": label,
                    "model_class_id": int(model_cls_id),
                    "model_class_name": model_class_names.get(int(model_cls_id), f"class_{int(model_cls_id)}"),
                    "confidence": round(float(conf), 4),
                    "polygon": [[round(float(x), 2), round(float(y), 2)] for x, y in polygon],
                }
            )
        return postprocess_detections(detections, image_shape)

    if result.obb is None or len(result.obb) == 0:
        return []
    polygons = result.obb.xyxyxyxy.cpu().numpy()
    classes = result.obb.cls.cpu().numpy().astype(int)
    confidences = result.obb.conf.cpu().numpy()
    for model_cls_id, conf, polygon in zip(classes, confidences, polygons):
        business_cls_id = model_to_business.get(int(model_cls_id))
        if business_cls_id is None:
            continue
        accessory_id = model_to_accessory_id.get(int(model_cls_id))
        class_name, label = detection_names_for_business_class(business_cls_id, spec)
        detections.append(
            {
                "class_id": business_cls_id,
                "accessory_id": accessory_id,
                "yolo_accessory_id": accessory_id,
                "resolved_accessory_id": accessory_id,
                "resolution_source": "yolo",
                "class_name": class_name,
                "label": label,
                "model_class_id": int(model_cls_id),
                "model_class_name": model_class_names.get(int(model_cls_id), f"class_{int(model_cls_id)}"),
                "confidence": round(float(conf), 4),
                "polygon": [[round(float(x), 2), round(float(y), 2)] for x, y in polygon],
            }
        )
    return postprocess_detections(detections, image_shape)


def apply_rule(detections: list[dict[str, Any]], config: dict[str, Any], spec: dict[str, Any]) -> dict[str, Any]:
    threshold = float(spec.get("confidence_threshold", config["confidence_threshold"]))
    if spec.get("is_specialized"):
        required_accessory_counts = {
            str(k): max(0, int(v))
            for k, v in (spec.get("required_accessory_counts") or {}).items()
        }
        if not required_accessory_counts:
            required_accessory_counts = {str(item_id): 1 for item_id in spec.get("selected_accessory_ids") or []}
        required_keys = list(required_accessory_counts.keys())
        class_labels = {str(k): str(v) for k, v in (spec.get("accessory_labels") or {}).items()}
        rule_source = "task"
        rule_task_id = spec.get("task_id")
        rule_label = " + ".join(str(x) for x in spec.get("accessory_names") or []) or str(spec.get("label") or "")
    else:
        required_keys = [int(x) for x in config["required_classes"]]
        required_accessory_counts = {}
        min_counts = {int(k): int(v) for k, v in config["min_counts"].items()}
        class_labels = {int(k): str(v) for k, v in CLASS_LABELS.items()}
        rule_source = "global"
        rule_task_id = None
        rule_label = "通用规则"
    count_by_rule_key: Counter[Any] = Counter()
    max_conf_by_rule_key: defaultdict[Any, float] = defaultdict(float)
    for det in detections:
        conf = float(det["confidence"])
        if conf >= threshold:
            rule_key: Any = str(det.get("resolved_accessory_id") or det.get("accessory_id")) if spec.get("is_specialized") else int(det["class_id"])
            if spec.get("is_specialized") and (not rule_key or rule_key == "None"):
                continue
            count_by_rule_key[rule_key] += 1
            max_conf_by_rule_key[rule_key] = max(max_conf_by_rule_key[rule_key], conf)

    missing = []
    present = []
    extra = []
    for rule_key in required_keys:
        need = required_accessory_counts.get(str(rule_key), min_counts.get(rule_key, 1) if not spec.get("is_specialized") else 1)
        found = count_by_rule_key.get(rule_key, 0)
        row = {
            "class_id": rule_key,
            "label": class_labels.get(rule_key, f"Class {rule_key}"),
            "required": need,
            "found": found,
            "max_confidence": round(max_conf_by_rule_key.get(rule_key, 0.0), 4),
        }
        if spec.get("is_specialized"):
            row["accessory_id"] = str(rule_key)
        if found == need:
            present.append(row)
        elif found > need:
            row["issue"] = "extra"
            extra.append(row)
            missing.append(row)
        else:
            row["issue"] = "missing"
            missing.append(row)

    manual_type_counts: Counter[str] = Counter()
    for det in detections:
        if int(det["class_id"]) == 1:
            manual_type = det.get("manual_type") or det.get("ocr", {}).get("manual_type")
            if manual_type and manual_type != "unknown":
                manual_type_counts[str(manual_type)] += 1

    ocr_config = config.get("ocr", {})
    required_manual_types = [str(x) for x in ocr_config.get("manual_types", MANUAL_TYPE_LABELS.keys())]
    manual_type_missing = []
    manual_type_present = []
    if not spec.get("is_specialized") and ocr_config.get("enabled", True) and ocr_config.get("require_manual_types", True):
        for manual_type in required_manual_types:
            row = {
                "manual_type": manual_type,
                "label": MANUAL_TYPE_LABELS.get(manual_type, manual_type),
                "required": 1,
                "found": manual_type_counts.get(manual_type, 0),
            }
            if row["found"] == 1:
                manual_type_present.append(row)
            else:
                row["issue"] = "extra" if row["found"] > 1 else "missing"
                manual_type_missing.append(row)

    passed = len(missing) == 0 and len(manual_type_missing) == 0
    return {
        "passed": passed,
        "threshold": threshold,
        "match_policy": "exact_count",
        "source": rule_source,
        "task_id": rule_task_id,
        "label": rule_label,
        "present": present,
        "missing": missing,
        "extra": extra,
        "counts": {class_labels.get(k, str(k)): v for k, v in sorted(count_by_rule_key.items(), key=lambda item: str(item[0]))},
        "ocr_enabled": bool(spec.get("uses_ocr", False) and ocr_config.get("enabled", True)),
        "manual_type_counts": {
            MANUAL_TYPE_LABELS.get(k, k): v for k, v in sorted(manual_type_counts.items())
        },
        "manual_type_present": manual_type_present,
        "manual_type_missing": manual_type_missing,
    }


def draw_detections(image_bgr: np.ndarray, detections: list[dict[str, Any]], rule: dict[str, Any]) -> np.ndarray:
    annotated = image_bgr.copy()
    overlay = image_bgr.copy()
    palette = {
        0: (38, 82, 255),
        1: (255, 120, 30),
    }
    for det in detections:
        cls_id = int(det["class_id"])
        color = palette.get(cls_id, (255, 255, 255))
        pts = np.array(det["polygon"], dtype=np.int32)
        cv2.fillPoly(overlay, [pts], color)
        cv2.polylines(annotated, [pts], isClosed=True, color=color, thickness=3, lineType=cv2.LINE_AA)
        x, y = pts[0]
        display_label = det.get("manual_label", det["label"])
        text = f"{display_label} {det['confidence']:.2f}"
        cv2.putText(annotated, text, (int(x), max(int(y) - 8, 22)), cv2.FONT_HERSHEY_SIMPLEX, 0.62, color, 2)

    annotated = cv2.addWeighted(overlay, 0.16, annotated, 0.84, 0)
    banner_color = (42, 150, 75) if rule["passed"] else (48, 60, 220)
    cv2.rectangle(annotated, (0, 0), (annotated.shape[1], 48), banner_color, -1)
    status = "TRUE: exact parts match" if rule["passed"] else "FALSE: count mismatch"
    cv2.putText(annotated, status, (18, 32), cv2.FONT_HERSHEY_SIMPLEX, 0.82, (255, 255, 255), 2)
    return annotated


def ai_required_accessories(config: dict[str, Any], spec: dict[str, Any]) -> list[tuple[dict[str, Any], int]]:
    accessories = config.get("accessories", [])
    by_id = {accessory_uid(item): item for item in accessories}
    required: list[tuple[dict[str, Any], int]] = []
    if spec.get("is_specialized"):
        counts = {
            str(k): max(1, int(v))
            for k, v in (spec.get("required_accessory_counts") or {}).items()
        }
        ids = [str(item_id) for item_id in spec.get("selected_accessory_ids") or counts.keys()]
        labels = {str(k): str(v) for k, v in (spec.get("accessory_labels") or {}).items()}
        for item_id in ids:
            item = by_id.get(item_id) or {
                "id": item_id,
                "class_id": -1,
                "name": labels.get(item_id, item_id),
                "material_type": "object",
                "source_files": [],
                "normalized_assets": [],
            }
            required.append((item, counts.get(item_id, 1)))
        return required

    required_classes = [int(x) for x in config.get("required_classes", [])]
    min_counts = {int(k): max(1, int(v)) for k, v in (config.get("min_counts") or {}).items()}
    by_class: dict[int, dict[str, Any]] = {}
    for item in accessories:
        try:
            by_class[int(item.get("class_id", -1))] = item
        except (TypeError, ValueError):
            continue
    for class_id in required_classes:
        item = by_class.get(class_id)
        if not item:
            item = {
                "id": f"required_class_{class_id}",
                "class_id": class_id,
                "name": CLASS_LABELS.get(class_id, f"Required Class {class_id}"),
                "material_type": "object" if class_id == 0 else "text",
                "status": "missing_accessory_metadata",
                "description": "Configured required class has no matching accessory metadata; fail closed.",
                "source_files": [],
                "normalized_assets": [],
            }
        required.append((item, min_counts.get(class_id, 1)))
    if required:
        return required
    return []


def ai_detection_task_payload(required_accessories: list[dict[str, Any]]) -> dict[str, Any]:
    payload_accessories = []
    for required in required_accessories:
        try:
            expected_count = max(1, int(required.get("expected_count") or 1))
        except (TypeError, ValueError):
            expected_count = 1
        profile = required.get("profile") if isinstance(required.get("profile"), dict) else {}
        text_cues = string_list(profile.get("distinguishing_text"), max_items=6, max_len=64)
        tags = string_list(profile.get("tags"), max_items=5, max_len=40)
        visual_signature = bounded_text(profile.get("visual_signature") or profile.get("description"), 180)
        payload_accessories.append(
            {
                "accessory_id": str(required.get("accessory_id") or ""),
                "name": bounded_text(required.get("name") or required.get("label") or required.get("accessory_id"), 80),
                "expected_count": expected_count,
                "material_type": bounded_text(required.get("material_type") or profile.get("material_type"), 32),
                "visual_cue": visual_signature,
                "text_cues": text_cues,
                "tags": tags,
            }
        )
    return {
        "task": {
            "policy": "presence_by_accessory_profile",
            "expected_latency_seconds": 5,
            "decision_rule": "passed is true only when every required accessory is present at exactly expected_count; undercounts and overcounts fail.",
            "output_mode": "compact",
            "required_accessories": payload_accessories,
        },
        "output_contract": {
            "detections": "Array of {accessory_id,label,present,confidence,count,evidence}. Count is optional unless multiple visible instances matter.",
            "rule": "Object with counts keyed by accessory_id.",
        },
    }


def ai_detection_output_token_budget(required_count: int) -> int:
    return max(180, min(420, 120 + max(1, required_count) * 64))


def ai_presence_failure_payload(
    required_accessories: list[dict[str, Any]],
    settings: dict[str, Any],
    *,
    reason: str,
    timed_out: bool = False,
    latency_ms: int = 0,
) -> dict[str, Any]:
    missing_ids = [str(item.get("accessory_id") or "") for item in required_accessories if item.get("accessory_id")]
    detections = [
        {
            "accessory_id": item_id,
            "label": bounded_text(required.get("name") or required.get("label") or item_id, 120),
            "present": False,
            "confidence": 0.0,
            "evidence": bounded_text(reason, 160),
            "observed_text": [],
        }
        for required in required_accessories
        for item_id in [str(required.get("accessory_id") or "")]
        if item_id
    ]
    provider_meta = ai_tool_provider_meta(settings)
    return {
        "tool": "vision.inspect.presence",
        "passed": len(missing_ids) == 0,
        "rule": {
            "match_policy": "ai_presence",
            "label": AI_DETECTION_LABEL,
            "present": [],
            "missing": missing_ids,
            "extra": [],
            "counts": {item_id: 0 for item_id in missing_ids},
        },
        "detections": detections,
        "ai": {
            "latency_ms": latency_ms,
            "timed_out": timed_out,
            "provider_failure": True,
            "failure_reason": bounded_text(reason, 240),
            "raw_summary": bounded_text(reason, 240),
            "provider_status": settings.get("status") or "",
            "error": bounded_text(reason, 240),
            **provider_meta,
        },
    }


def ai_detection_failure_result(
    request_id: str,
    spec: dict[str, Any],
    required_items: list[tuple[dict[str, Any], int]],
    annotated_url: str,
    *,
    reason: str,
    timed_out: bool = False,
    latency_ms: int = 0,
) -> dict[str, Any]:
    settings = ai_detection_settings()
    required_accessories = [required_accessory_profile_payload(item, expected_count) for item, expected_count in required_items]
    payload = ai_presence_failure_payload(required_accessories, settings, reason=reason, timed_out=timed_out, latency_ms=latency_ms)
    return {
        "request_id": request_id,
        "passed": payload["passed"],
        "model": ai_model_payload(spec, settings),
        "rule": payload["rule"],
        "detections": payload["detections"],
        "annotated_url": annotated_url,
        "ai": payload["ai"],
    }


def write_ai_original_output(image_bgr: np.ndarray, request_id: str) -> str:
    out_name = f"{request_id}_ai_original.jpg"
    out_path = output_write_dir("ai_detection") / out_name
    cv2.imwrite(str(out_path), image_bgr, [int(cv2.IMWRITE_JPEG_QUALITY), 92])
    return output_url(out_path)


def normalize_ai_box_2d(value: Any) -> list[float] | None:
    if not isinstance(value, (list, tuple)) or len(value) != 4:
        return None
    coords: list[float] = []
    for raw in value:
        if type(raw) not in (int, float):
            return None
        coord = float(raw)
        if not math.isfinite(coord):
            return None
        coords.append(max(0.0, min(1000.0, coord)))
    y_min, x_min, y_max, x_max = coords
    if y_max <= y_min or x_max <= x_min:
        return None
    return [round(coord, 2) for coord in coords]


def ai_box_2d_to_pixels(box_2d: Any, image_shape: tuple[int, ...]) -> tuple[int, int, int, int] | None:
    box = normalize_ai_box_2d(box_2d)
    if not box:
        return None
    h, w = image_shape[:2]
    if h <= 1 or w <= 1:
        return None
    y_min, x_min, y_max, x_max = box
    x1 = max(0, min(w - 1, int(math.floor(x_min / 1000.0 * (w - 1)))))
    y1 = max(0, min(h - 1, int(math.floor(y_min / 1000.0 * (h - 1)))))
    x2 = max(0, min(w - 1, int(math.ceil(x_max / 1000.0 * (w - 1)))))
    y2 = max(0, min(h - 1, int(math.ceil(y_max / 1000.0 * (h - 1)))))
    if x2 <= x1 or y2 <= y1:
        return None
    return x1, y1, x2, y2


def draw_ai_detection_boxes(image_bgr: np.ndarray, detections: list[dict[str, Any]], rule: dict[str, Any]) -> np.ndarray | None:
    boxes: list[tuple[dict[str, Any], tuple[int, int, int, int]]] = []
    for det in detections:
        if not isinstance(det, dict):
            continue
        xyxy = ai_box_2d_to_pixels(det.get("box_2d"), image_bgr.shape)
        if xyxy:
            boxes.append((det, xyxy))
    if not boxes:
        return None

    annotated = image_bgr.copy()
    overlay = image_bgr.copy()
    color = (32, 196, 92) if bool(rule.get("passed")) else (40, 180, 255)
    thickness = max(2, int(round(min(image_bgr.shape[:2]) / 220)))
    font_scale = max(0.45, min(0.7, min(image_bgr.shape[:2]) / 640.0))
    font_thickness = max(1, thickness - 1)
    for det, (x1, y1, x2, y2) in boxes:
        cv2.rectangle(overlay, (x1, y1), (x2, y2), color, -1)
        cv2.rectangle(annotated, (x1, y1), (x2, y2), color, thickness, cv2.LINE_AA)
        label = bounded_text(det.get("label") or det.get("accessory_id") or "AI", 24)
        try:
            confidence = float(det.get("confidence") or 0.0)
        except (TypeError, ValueError):
            confidence = 0.0
        text = f"{label} {confidence:.2f}" if confidence > 0 else label
        (text_w, text_h), baseline = cv2.getTextSize(text, cv2.FONT_HERSHEY_SIMPLEX, font_scale, font_thickness)
        label_y1 = max(0, y1 - text_h - baseline - 6)
        label_y2 = min(image_bgr.shape[0] - 1, label_y1 + text_h + baseline + 6)
        label_x2 = min(image_bgr.shape[1] - 1, x1 + text_w + 10)
        cv2.rectangle(annotated, (x1, label_y1), (label_x2, label_y2), color, -1)
        cv2.putText(
            annotated,
            text,
            (x1 + 5, max(text_h + 2, label_y2 - baseline - 3)),
            cv2.FONT_HERSHEY_SIMPLEX,
            font_scale,
            (255, 255, 255),
            font_thickness,
            cv2.LINE_AA,
        )
    return cv2.addWeighted(overlay, 0.10, annotated, 0.90, 0)


def write_ai_annotated_output(image_bgr: np.ndarray, request_id: str, detections: list[dict[str, Any]], rule: dict[str, Any]) -> str:
    annotated = draw_ai_detection_boxes(image_bgr, detections, rule)
    if annotated is None:
        return write_ai_original_output(image_bgr, request_id)
    out_name = f"{request_id}_ai_annotated.jpg"
    out_path = output_write_dir("ai_detection") / out_name
    cv2.imwrite(str(out_path), annotated, [int(cv2.IMWRITE_JPEG_QUALITY), 92])
    return output_url(out_path)


def ai_model_payload(spec: dict[str, Any], settings: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": spec["id"],
        "label": spec.get("label", AI_DETECTION_LABEL),
        "variant": "ai_detection",
        "is_ai_detection": True,
        "provider_model": settings.get("model") or "",
        "uses_ocr": True,
        "task_id": spec.get("task_id") or "",
        "task_label": spec.get("task_label") or "",
        "selected_accessory_ids": spec.get("selected_accessory_ids") or [],
        "required_accessory_counts": spec.get("required_accessory_counts") or {},
        "accessory_names": spec.get("accessory_names") or [],
        "accessory_labels": spec.get("accessory_labels") or {},
    }


def normalize_ai_detection_result(
    parsed: dict[str, Any],
    required_accessories: list[dict[str, Any]],
    latency_ms: int,
    settings: dict[str, Any],
) -> dict[str, Any]:
    raw_detections = parsed.get("detections") if isinstance(parsed.get("detections"), list) else []
    raw_by_id = {
        str(det.get("accessory_id")): det
        for det in raw_detections
        if isinstance(det, dict) and det.get("accessory_id") is not None
    }
    raw_rule = parsed.get("rule") if isinstance(parsed.get("rule"), dict) else {}
    raw_counts = raw_rule.get("counts") if isinstance(raw_rule.get("counts"), dict) else {}
    detections = []
    present_ids = []
    missing_ids = []
    counts: dict[str, int] = {}
    count_mismatches: dict[str, dict[str, Any]] = {}
    overcount_ids: list[str] = []
    for required in required_accessories:
        item_id = str(required.get("accessory_id") or "")
        if not item_id:
            continue
        try:
            expected_count = max(1, int(required.get("expected_count") or 1))
        except (TypeError, ValueError):
            expected_count = 1
        raw = raw_by_id.get(item_id, {})
        raw_confidence = raw.get("confidence", 0.5 if raw.get("present") is True else 0.0) if isinstance(raw, dict) else 0.0
        try:
            if isinstance(raw_confidence, bool):
                raise ValueError("confidence must be numeric")
            confidence_value = float(raw_confidence)
            if not math.isfinite(confidence_value):
                raise ValueError("confidence must be finite")
            confidence = max(0.0, min(1.0, confidence_value))
        except (TypeError, ValueError):
            confidence = 0.0
        provider_present = isinstance(raw, dict) and raw.get("present") is True
        present = provider_present and confidence > 0.0
        has_raw_count = item_id in raw_counts
        raw_count = raw_counts.get(item_id)
        if has_raw_count:
            count = raw_count if type(raw_count) is int and raw_count >= 0 else 0
        elif isinstance(raw, dict) and type(raw.get("count")) is int and raw.get("count") >= 0:
            count = raw["count"]
        else:
            count = 1 if present else 0
        if not present:
            count = 0
        counts[item_id] = count
        if present and count == expected_count:
            present_ids.append(item_id)
        else:
            missing_ids.append(item_id)
            if present or count != expected_count:
                issue = "over_count" if count > expected_count else "under_count"
                count_mismatches[item_id] = {
                    "expected": expected_count,
                    "found": count,
                    "issue": issue,
                }
                if count > expected_count:
                    overcount_ids.append(item_id)
        detection = {
            "accessory_id": item_id,
            "label": bounded_text(raw.get("label") if isinstance(raw, dict) else required.get("name"), 120)
            or bounded_text(required.get("name") or item_id, 120),
            "present": item_id in present_ids,
            "confidence": round(confidence, 4),
            "evidence": bounded_text(raw.get("evidence") if isinstance(raw, dict) else "", 180),
            "observed_text": string_list(raw.get("observed_text") if isinstance(raw, dict) else [], max_items=6, max_len=80),
        }
        if count > 1 or expected_count > 1 or (isinstance(raw, dict) and "count" in raw):
            detection["count"] = count
        detections.append(detection)
    required_ids = {str(item.get("accessory_id") or "") for item in required_accessories}
    raw_extra = [item for item in raw_rule.get("extra", []) if str(item) not in required_ids] if isinstance(raw_rule.get("extra"), list) else []
    extra = string_list([*raw_extra, *overcount_ids], max_items=12)
    passed = len(missing_ids) == 0
    provider_meta = ai_tool_provider_meta(settings)
    return {
        "tool": "vision.inspect.presence",
        "passed": passed,
        "rule": {
            "match_policy": "ai_presence",
            "label": AI_DETECTION_LABEL,
            "present": present_ids,
            "missing": missing_ids,
            "extra": extra,
            "counts": counts,
            "count_mismatches": count_mismatches,
        },
        "detections": detections,
        "ai": {
            "latency_ms": latency_ms,
            "timed_out": False,
            "provider_failure": False,
            "raw_summary": bounded_text(parsed.get("raw_summary") or parsed.get("summary") or "", 240),
            "provider_status": settings.get("status") or "",
            **provider_meta,
        },
    }


def analyze_bgr_ai_detection(
    image_bgr: np.ndarray,
    request_id: str,
    spec: dict[str, Any],
    config: dict[str, Any],
    *,
    image_path: Path | None = None,
) -> dict[str, Any]:
    required_items = ai_required_accessories(config, spec)
    if not required_items:
        annotated_url = write_ai_original_output(image_bgr, request_id)
        result = ai_detection_failure_result(
            request_id,
            spec,
            [],
            annotated_url,
            reason="AI detection task has no required accessories configured.",
        )
        persist_data_analysis_record_for_ai_detection(result, request_id, image_path=image_path)
        return result
    changed = False
    real_ids = {accessory_uid(item) for item in config.get("accessories", [])}
    required_accessories: list[dict[str, Any]] = []
    required_accessory_refs: list[dict[str, Any]] = []
    reference_descriptors: list[dict[str, Any]] = []
    for item, expected_count in required_items:
        item_id = accessory_uid(item)
        current_profile = item.get("ai_profile") if isinstance(item.get("ai_profile"), dict) else None
        if not current_profile or current_profile.get("accessory_id") != item_id:
            profile_result = call_ai_mcp_tool(
                "accessory.profile.generate",
                {
                    "accessory": item,
                    "expected_count": expected_count,
                    "allow_provider": False,
                    "provider_config": ai_detection_settings(),
                },
            )
            item["ai_profile"] = profile_result["profile"]
            item["ai_profile_status"] = profile_result["status"]
            current_profile = profile_result["profile"]
            if item_id in real_ids:
                changed = True
        else:
            normalized_profile = normalize_accessory_ai_profile(current_profile, item)
            current_refs = normalized_profile.get("reference_images") if isinstance(normalized_profile.get("reference_images"), list) else []
            if current_refs:
                if normalized_profile != current_profile:
                    item["ai_profile"] = normalized_profile
                    current_profile = normalized_profile
                    if item_id in real_ids:
                        changed = True
            else:
                expected_refs = accessory_reference_image_contexts(item)
                if expected_refs:
                    normalized_profile["reference_images"] = expected_refs
                    item["ai_profile"] = normalized_profile
                    current_profile = normalized_profile
                    if item_id in real_ids:
                        changed = True
        required_accessories.append(required_accessory_profile_payload(item, expected_count, current_profile))
        required_accessory_refs.append({"accessory_id": item_id, "expected_count": expected_count})
        if AI_REFERENCE_IMAGES_PER_ACCESSORY > 0:
            reference_result = call_ai_mcp_tool(
                "accessory.reference.collect",
                {
                    "accessory": item,
                    "max_images": AI_REFERENCE_IMAGES_PER_ACCESSORY,
                    "max_side": AI_REFERENCE_IMAGE_MAX_SIDE,
                    "quality": AI_REFERENCE_IMAGE_QUALITY,
                },
            )
            reference_descriptors.extend(reference_result.get("references") or [])
    if changed:
        save_config(config)
    settings = ai_detection_settings()
    mcp_image_path = write_mcp_inspection_image(image_bgr, request_id) if external_ai_mcp_enabled() else None
    vision_result = call_ai_mcp_tool(
        "vision.inspect.presence",
        {
            "inspection_image_bgr": image_bgr,
            "inspection_image_path": str(mcp_image_path) if mcp_image_path else "",
            "required_accessories": required_accessories,
            "required_accessory_refs": required_accessory_refs,
            "reference_descriptors": reference_descriptors,
            "provider_config": settings,
        },
    )
    ai_debug = vision_result.get("ai") if isinstance(vision_result.get("ai"), dict) else {}
    for key in ("mcp_transport", "mcp_runtime", "mcp_dispatch_ms", "mcp_fallback_from", "mcp_fallback_error"):
        if vision_result.get(key) is not None:
            ai_debug = {**ai_debug, key: vision_result.get(key)}
    rule = vision_result.get("rule") if isinstance(vision_result.get("rule"), dict) else {}
    detections = vision_result.get("detections") if isinstance(vision_result.get("detections"), list) else []
    annotated_url = write_ai_original_output(image_bgr, request_id)
    result = {
        "request_id": request_id,
        "passed": bool(vision_result.get("passed")),
        "model": ai_model_payload(spec, settings),
        "rule": rule,
        "detections": detections,
        "annotated_url": annotated_url,
        "ai": ai_debug,
    }
    persist_data_analysis_record_for_ai_detection(result, request_id, image_path=image_path)
    return result


def analyze_bgr(image_bgr: np.ndarray, request_id: str, model_id: str | None = None, *, image_path: Path | None = None) -> dict[str, Any]:
    config = scope_config_for_user(load_config())
    spec = selected_model_spec(model_id, config)
    if spec.get("is_ai_detection"):
        return analyze_bgr_ai_detection(image_bgr, request_id, spec, config, image_path=image_path)
    if spec.get("is_label_sheet_match"):
        return analyze_bgr_label_sheet(image_bgr, request_id, config)
    try:
        confidence_threshold = max(0.001, min(0.99, float(spec.get("confidence_threshold", config.get("confidence_threshold", 0.25)))))
    except (TypeError, ValueError):
        confidence_threshold = 0.25
    result = model(str(spec["id"]), config).predict(
        image_bgr,
        imgsz=int(config["image_size"]),
        device=yolo_inference_device(),
        conf=confidence_threshold,
        verbose=False,
    )[0]
    detections = parse_detections(result, spec)
    if spec.get("uses_ocr", False):
        detections = attach_ocr_results(image_bgr, detections, config, spec)
    rule = apply_rule(detections, config, spec)
    annotated = draw_detections(image_bgr, detections, rule)
    out_name = f"{request_id}_annotated.jpg"
    out_path = output_write_dir("inspection") / out_name
    cv2.imwrite(str(out_path), annotated, [int(cv2.IMWRITE_JPEG_QUALITY), 92])
    return {
        "request_id": request_id,
        "passed": rule["passed"],
        "model": {
            "id": spec["id"],
            "label": spec["label"],
            "uses_ocr": bool(spec.get("uses_ocr", False)),
        },
        "rule": rule,
        "detections": detections,
        "annotated_url": output_url(out_path),
    }


@app.get("/api/auth/status")
def auth_status(request: Request) -> dict[str, Any]:
    user, store, _ = authenticate_request(request)
    setup_required = not users_exist(store)
    return {
        "authenticated": bool(user),
        "setup_required": setup_required,
        "user": user,
        "features": FEATURE_PERMISSIONS,
        "default_user_permissions": DEFAULT_USER_PERMISSIONS,
        "legacy_owner_id": LEGACY_OWNER_ID,
    }


@app.post("/api/auth/bootstrap")
def auth_bootstrap(request: Request, response: Response, payload: AuthBootstrapRequest) -> dict[str, Any]:
    store = load_auth_store()
    if users_exist(store):
        raise HTTPException(status_code=409, detail="First admin already exists")
    user = create_auth_user(
        store,
        username=payload.username,
        password=payload.password,
        display_name=payload.display_name,
        role="admin",
        permissions=sorted(FEATURE_PERMISSIONS),
    )
    session_id = create_session(store, user)
    save_auth_store(store)
    set_session_cookie(response, request, session_id)
    return {"status": "created", "user": public_user(user), "features": FEATURE_PERMISSIONS}


@app.post("/api/auth/login")
def auth_login(request: Request, response: Response, payload: AuthLoginRequest) -> dict[str, Any]:
    store = load_auth_store()
    if bootstrap_admin_from_env(store):
        store = load_auth_store()
    if not users_exist(store):
        raise HTTPException(status_code=409, detail="First admin setup required")
    user = find_user_by_username(store, payload.username)
    if not user or not bool(user.get("active", True)) or not verify_password(payload.password, str(user.get("password_hash") or "")):
        raise HTTPException(status_code=401, detail="Invalid username or password")
    session_id = create_session(store, user)
    save_auth_store(store)
    set_session_cookie(response, request, session_id)
    return {"status": "authenticated", "user": public_user(user), "features": FEATURE_PERMISSIONS}


@app.post("/api/auth/logout")
def auth_logout(request: Request, response: Response) -> dict[str, Any]:
    store = load_auth_store()
    session_id = request.cookies.get(AUTH_SESSION_COOKIE, "")
    if session_id and isinstance(store.get("sessions"), dict):
        store["sessions"].pop(session_id, None)
        save_auth_store(store)
    clear_session_cookie(response, request)
    return {"status": "logged_out"}


